package com.portfolio.features.education.entity; import com.portfolio.features.portfolio.entity.Portfolio; import jakarta.persistence.*; import java.time.*; import java.util.*; import lombok.*; @Entity @Table(name="educations") @Getter @Setter @NoArgsConstructor public class Education { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="portfolio_id") private Portfolio portfolio; @Column(nullable=false) private String school; private String degree, major; private LocalDate startDate,endDate; @Column(columnDefinition="TEXT") private String description; private int sortOrder; private LocalDateTime createdAt,updatedAt; @PrePersist void create(){createdAt=updatedAt=LocalDateTime.now();}@PreUpdate void update(){updatedAt=LocalDateTime.now();} }
